(()=>{const out={},run=(n,f)=>{document.title=n;try{out[n]=f()}catch(e){out[n]={error:e.name}}};for(const [kind,d]of [['active',document],['inert',document.implementation.createHTMLDocument('')],['xml',new DOMParser().parseFromString('<root/>','text/xml')]]){for(const [key,values]of [['designMode',['on','ON','inherit','off','xxx']],['xmlVersion',['1.0','1.1','x']],['xmlStandalone',[true,false]],['fgColor',['red','#abcdef','garbage','']],['bgColor',['blue',null]]])run(kind+'.mutate.'+key,()=>values.map(v=>{try{d[key]=v;return [d[key],d.body?.getAttribute(key==='fgColor'?'text':key.toLowerCase())??null]}catch(e){return e.name}}))}document.title='done';return out})()